require_once dirname(__DIR__, 3) . '/bootstrap.php'; $allowedRoles=[ROLE_HOUSE_MASTER,ROLE_HOUSE_MISTRESS]; require APP_ROOT.'/app/middleware/RoleMiddleware.php'; use App\Services\IncidentService; use App\Services\StudentService;
$houseId=current_user()['houseId']??null;$incidents=(new IncidentService())->byHouse($houseId);$students=StudentService::all($houseId);$studentMap=[];foreach($students as $student)$studentMap[(string)($student['id']??'')]=$student;$statusCounts=[];$priorityCounts=[];foreach($incidents as $incident){$status=(string)($incident['status']??'open');$priority=(string)($incident['priority']??$incident['severity']??'low');$statusCounts[$status]=($statusCounts[$status]??0)+1;$priorityCounts[$priority]=($priorityCounts[$priority]??0)+1;}$pageTitle='Incident Report';$navItems=[['icon'=>'bi-file-earmark-text','label'=>'Reports','href'=>url('views/house-master/reports/index.php'),'active'=>true]];require APP_ROOT.'/app/views/components/header.php';require APP_ROOT.'/app/views/components/sidebar.php';?>
<div class="main-content"><?php require APP_ROOT.'/app/views/components/navbar.php';?><div class="content-wrapper"><div class="d-flex justify-content-between mb-3"><div><h5 class="mb-1">Incident Report</h5><p class="text-muted mb-0">Open and resolved incidents across your house.</p></div><a class="btn btn-outline-primary btn-sm" href="<?=url('views/house-master/incidents/index.php')?>">Open incident log</a></div><div class="row g-3 mb-3"><div class="col-md-6"><div class="card stat-card p-3"><h6>Status breakdown</h6><?php foreach($statusCounts as $status=>$count):?><div class="d-flex justify-content-between border-bottom py-2"><span><?=e(ucfirst($status))?></span><strong><?=e((string)$count)?></strong></div><?php endforeach;?></div></div><div class="col-md-6"><div class="card stat-card p-3"><h6>Priority breakdown</h6><?php foreach($priorityCounts as $priority=>$count):?><div class="d-flex justify-content-between border-bottom py-2"><span><?=e(ucfirst($priority))?></span><strong><?=e((string)$count)?></strong></div><?php endforeach;?></div></div></div><div class="card stat-card p-3"><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Student</th><th>Title</th><th>Priority</th><th>Status</th><th>Reported</th></tr></thead><tbody><?php foreach($incidents as $incident):$student=$studentMap[(string)($incident['studentId']??'')]??[];?><tr><td><?=e(trim(($student['firstName']??'').' '.($student['lastName']??''))?:($incident['studentId']??'-'))?></td><td><?=e($incident['title']??$incident['type']??'Incident')?></td><td><?=e($incident['priority']??$incident['severity']??'low')?></td><td><?=e($incident['status']??'open')?></td><td><?=e(substr((string)($incident['reportedAt']??$incident['createdAt']??''),0,10))?></td></tr><?php endforeach;?></tbody></table></div></div></div></div><?php require APP_ROOT.'/app/views/components/footer.php';?>